import 'package:flutter/material.dart';import '../api/gaon_api.dart';class AccountScreen extends StatefulWidget{final VoidCallback onLogout;const AccountScreen({super.key,required this.onLogout});@override State<AccountScreen> createState()=>_AccountScreenState();}class _AccountScreenState extends State<AccountScreen>{final business=TextEditingController(),gstin=TextEditingController();bool busy=false;Future<void> apply()async{if(business.text.trim().length<2)return;setState(()=>busy=true);try{await GaonApi.applyMerchant(business.text.trim(),gstin:gstin.text.trim().isEmpty?null:gstin.text.trim());if(!mounted)return;await showDialog(context:context,builder:(c)=>AlertDialog(title:const Text('Merchant application submitted'),content:const Text('Your account is now in merchant review. Sign in again to open the merchant workspace and track approval.'),actions:[FilledButton(onPressed:()=>Navigator.pop(c),child:const Text('Continue'))]));widget.onLogout();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[Text('Account',style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:12),const Card(child:ListTile(leading:Icon(Icons.verified_user_outlined),title:Text('Verified GaonOne account'),subtitle:Text('Your phone identity is used for orders, merchant access and delivery operations.'))),const SizedBox(height:16),Text('Sell on GaonOne',style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w700)),const Text('Apply as a local merchant. Admin approval is required before your storefront becomes public.'),const SizedBox(height:12),TextField(controller:business,decoration:const InputDecoration(labelText:'Business / shop name')),const SizedBox(height:10),TextField(controller:gstin,decoration:const InputDecoration(labelText:'GSTIN (optional)')),const SizedBox(height:10),FilledButton.icon(onPressed:busy?null:apply,icon:const Icon(Icons.storefront),label:Text(busy?'Submitting…':'Apply as merchant')),const SizedBox(height:28),OutlinedButton.icon(onPressed:widget.onLogout,icon:const Icon(Icons.logout),label:const Text('Log out'))]);}
